contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= value, "insufficient balance for withdraw");

        uint cBalanceBefore = address(c).balance;
        uint selfBalanceBefore = address(this).balance;

        bool reverted;
        c.withdraw(value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint cBalanceAfter = address(c).balance;
        uint selfBalanceAfter = address(this).balance;

        assert(reverted || (cBalanceBefore - cBalanceAfter == value && selfBalanceAfter - selfBalanceBefore == value));
    }

    receive() external payable {}
}

